      SUBROUTINE RFITCC     CONSTRAINS R MATRIXC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'ELM10A.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'ELM10D.CIN'      INCLUDE 'ELM15C.CIN'      INCLUDE 'RC.CIN'      INCLUDE 'RCP.CIN'      INCLUDE 'RC2.CIN'      INCLUDE 'R2P.CIN'C-----------------------------------------------------------------------      LOGICAL         LOGICCC     VALUE OF MATRIX ELEMENTC      J = JCON      K = KCON      J = - J      FAC = UBEAM(K)/UBEAM(J)C      IF (RCP) GO TO 10      RCT = RC2(J,K)      GO TO 50C   10 IF (R2P) GO TO 20      RCT = RC(J,K)      GO TO 50C   20 RCT = 0.0      DO 30 L1 = 1, 6      RCT = RCT + RC2(J,L1)*RC(L1,K)   30 CONTINUEC   50 COC = RCT*FAC      IF (NV3 .LT. 1) GO TO 100      CW = 1.0/SD**2      A(1) = DE0 - COC      CALL CLI(LOGIC)      IF (LOGIC) GO TO 150CC     PARTIAL DERIVATIVESC      IF (NV1 .LT. 1) GO TO 100      DO 90 N = 1, NV1      RCTV = 0.0      IF (.NOT. (RVP(N) .OR. R2VP(N))) GO TO 80      IF (RCP) GO TO 55      RCTV = R2V(J,K,N)      GO TO 80C   55 IF (R2P) GO TO 60      RCTV = RCV(J,K,N)      GO TO 80C   60 IF (R2VP(N)) GO TO  70      DO 65 L1 = 1, 6      RCTV = RCTV + RC2(J,L1)*RCV(L1,K,N)   65 CONTINUE      GO TO 80C   70 IF (RVP(N)) THEN        DO 75 L1 = 1, 6        RCTV = RCTV + R2V(J,L1,N)*RC(L1,K) + RC2(J,L1)*RCV(L1,K,N)   75   CONTINUE      ELSE        DO 77 L1 = 1, 6        RCTV = RCTV + R2V(J,L1,N)*RC(L1,K)   77   CONTINUE      ENDIF   80 A(N+1) = RCTV*FACC   90 CONTINUE  100 CALL GATHER      IF (NV1 .LT. 1) GO TO 150C  150 RETURN      END